class MockWarehouse : public Warehouse {
 public:
  MOCK_METHOD(bool, hasInventory, (const std::string&, int), (override));
  MOCK_METHOD(void, remove, (const std::string&, int), (override));
};

TEST(OrderTest, FillsFromWarehouse) {
  MockWarehouse warehouse;
  EXPECT_CALL(warehouse, hasInventory("Talisker", 50)).WillOnce(Return(true));
  EXPECT_CALL(warehouse, remove("Talisker", 50)).Times(1);
  EXPECT_TRUE(Order("Talisker", 50).fill(warehouse));
}

